import java.io.*;
import java.util.*;

interface SemiRing<T> {
    T zero();
    T one();
    T add(T other);
    T mul(T other);
}

class SquareMatrix<T extends SemiRing<T>> {
    int n;
    T[] a;

    @SuppressWarnings("unchecked")
    public SquareMatrix(int n, T zero) {
        this.n = n;
        this.a = (T[]) new SemiRing[n * n];
        for (int i = 0; i < n * n; i++) {
            this.a[i] = zero;
        }
    }

    public static <T extends SemiRing<T>> SquareMatrix<T> zero(int n, T zero) {
        return new SquareMatrix<>(n, zero);
    }

    public static <T extends SemiRing<T>> SquareMatrix<T> identity(int n, T zero, T one) {
        SquareMatrix<T> m = zero(n, zero);
        for (int i = 0; i < n; i++) {
            m.a[i * n + i] = one;
        }
        return m;
    }

    public void set_at(int i, int j, T v) {
        this.a[i * this.n + j] = v;
    }

    public T get_at(int i, int j) {
        return this.a[i * this.n + j];
    }

    public static <T extends SemiRing<T>> SquareMatrix<T> matmul(SquareMatrix<T> l, SquareMatrix<T> r) {
        return l.mul(r);
    }

    public SquareMatrix<T> add(SquareMatrix<T> rhs) {
        int n = this.n;
        SquareMatrix<T> c = zero(n, this.a[0].zero());
        for (int i = 0; i < n * n; i++) {
            c.a[i] = this.a[i].add(rhs.a[i]);
        }
        return c;
    }

    public SquareMatrix<T> mul(SquareMatrix<T> rhs) {
        int n = this.n;
        SquareMatrix<T> c = zero(n, this.a[0].zero());
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                T aVal = this.a[i * n + k];
                for (int j = 0; j < n; j++) {
                    int idxC = i * n + j;
                    int idxR = k * n + j;
                    c.a[idxC] = c.a[idxC].add(aVal.mul(rhs.a[idxR]));
                }
            }
        }
        return c;
    }

    @SuppressWarnings("unchecked")
    public SquareMatrix<T> cloneMatrix() {
        SquareMatrix<T> m = new SquareMatrix<>(this.n, this.a[0].zero());
        for (int i = 0; i < this.a.length; i++) {
            m.a[i] = this.a[i];
        }
        return m;
    }
}

class ModInt implements SemiRing<ModInt> {
    public static final int MOD = 1000000007;
    public int v;

    public ModInt(int v) {
        this.v = v % MOD;
        if (this.v < 0) this.v += MOD;
    }

    public ModInt zero() {
        return new ModInt(0);
    }

    public ModInt one() {
        return new ModInt(1);
    }

    public ModInt add(ModInt other) {
        int d = this.v + other.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    public ModInt sub(ModInt other) {
        int d = this.v + MOD - other.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    public ModInt mul(ModInt other) {
        long res = (long) this.v * (long) other.v % MOD;
        return new ModInt((int) res);
    }

    public ModInt neg() {
        if (this.v == 0) return new ModInt(0);
        return new ModInt(MOD - this.v);
    }

    public ModInt pow(int n) {
        ModInt t = new ModInt(1);
        ModInt s = new ModInt(this.v);
        int e = n;
        while (e > 0) {
            if ((e & 1) == 1) {
                t = t.mul(s);
            }
            s = s.mul(s);
            e >>= 1;
        }
        return t;
    }

    public ModInt div(ModInt other) {
        return this.mul(other.pow(MOD - 2));
    }

    public String toString() {
        return Integer.toString(this.v);
    }
}

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static void run() throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        int m = fs.nextInt();

        ModInt zero = new ModInt(0);
        ModInt one = new ModInt(1);

        SquareMatrix<ModInt> t = SquareMatrix.identity(m, zero, one);
        SquareMatrix<ModInt> s = SquareMatrix.zero(m, zero);

        for (int i = 1; i < m; i++) {
            s.set_at(i - 1, i, new ModInt(1));
        }
        s.set_at(m - 1, 0, new ModInt(1));
        s.set_at(m - 1, m - 1, new ModInt(1));

        long nn = n;
        while (nn > 0) {
            if ((nn & 1) == 1) {
                t = t.mul(s.cloneMatrix());
            }
            s = s.cloneMatrix().mul(s);
            nn >>= 1;
        }
        ModInt ans = t.get_at(m - 1, m - 1);
        System.out.println(ans);
    }

    public static void main(String[] args) throws Exception {
        run();
    }
}

